/// Walks AST nodes and invokes their traversal hooks.
pub trait TraverseWith<'a, 'id, State = ()> {
    fn traverse_with<T: ?Sized + Traverse<'a, 'id, State>>(
        self,
        traverser: &mut T,
        ctx: &mut TraverseCtx<'_, 'a, 'id, State>,
    );
}
impl<'a, 'id, State> TraverseWith<'a, 'id, State> for Program<'id> {
    #[inline]
    fn traverse_with<T: ?Sized + Traverse<'a, 'id, State>>(
        self,
        traverser: &mut T,
        ctx: &mut TraverseCtx<'_, 'a, 'id, State>,
    ) {
        {
            let node_id = (self).node_id();
            traverser.enter_node(node_id, ctx);
            walk_program(self, traverser, ctx);
            traverser.exit_node(node_id, ctx);
        }
    }
}
impl<'a, 'id, State> TraverseWith<'a, 'id, State> for Stmt<'id> {
    #[inline]
    fn traverse_with<T: ?Sized + Traverse<'a, 'id, State>>(
        self,
        traverser: &mut T,
        ctx: &mut TraverseCtx<'_, 'a, 'id, State>,
    ) {
        {
            let node_id = (self).node_id();
            traverser.enter_node(node_id, ctx);
            traverser.enter_stmt(self, ctx);
            walk_stmt(self, traverser, ctx);
            traverser.exit_stmt(self, ctx);
            traverser.exit_node(node_id, ctx);
        }
    }
}
