impl<'a, 'id, State> TraverseMutWith<'a, 'id, State> for SubRange<'id, Directive<'id>> {
    #[inline]
    fn traverse_mut_with<T: ?Sized + TraverseMut<'a, 'id, State>>(
        self,
        traverser: &mut T,
        ctx: &mut TraverseMutCtx<'_, 'a, 'id, State>,
    ) -> TraverseAction<Self> {
        for slot in self.iter() {
            if traverse_mut_slot(
                ctx.ast.get_node_in_sub_range(slot),
                traverser,
                ctx,
                |ctx, replacement| self.replace_slot(ctx.ast, slot, replacement),
            ) {
                return TraverseAction::Stop;
            }
        }
        TraverseAction::Continue
    }
}
